import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Onboarding — недоступен зарегистрированному', () => {
  test('OB-01 Зарегистрированный пользователь не попадает в onboarding по URL #6aa7f009 @prod-safe', async ({ page }) => {
    // 1. По очереди открыть маршруты onboarding; каждый перенаправляет на `/home`.
    const routes = ['/level', '/summary', '/birth-date', '/dates', '/location', '/reminders', '/motivation', '/nusach', '/register', '/welcome'];
    for (const route of routes) {
      await page.goto(route);
      await expect(page, `маршрут ${route}`).toHaveURL(/\/home$/, { timeout: 15_000 });
    }
  });
});
